editorial:
For each length retain the smallest possible last value, which offers the most room for future values. These tails increase strictly. Replace the first tail at least x, or append x if none exists. Equal values replace a tail without extending the length. Time O(n log n), space O(n).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin>>n;
    vector<int>tails;
    while(n--) {
        int x; cin>>x;
        auto at=lower_bound(tails.begin(),tails.end(),x);
        if(at==tails.end()) tails.push_back(x);
        else *at=x;
        cout<<tails.size()<<'\n';
    }
}
